def weekly_open(now=None):
    """Сколько задач недели уже открылось (первая — в день WEEKLY_START)."""
    import time as _t
    start = _t.mktime(_t.strptime(WEEKLY_START, "%Y-%m-%d"))
    weeks = int(((now or _t.time()) - start) // (7 * 86400)) + 1
    return max(0, min(len(WEEKLY), weeks))
